ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('bc4474ed-3cc8-5bc7-b8d1-6522c62c19d1'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Sur quel continent l’humanité apparaît-elle ?', 'mcq', '["En Afrique","En Europe","En Asie","En Amérique"]'::jsonb, 0, 'Homo sapiens y naît également.', 1),
    ('adf88e92-6ebe-59f7-81ce-fbed31211ab6'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Comment appelle-t-on la période des premiers humains ?', 'mcq', '["Le Paléolithique","Le Néolithique","L’Antiquité","Le Moyen Âge"]'::jsonb, 0, 'Elle représente plus de 99 % du temps de l’humanité.', 2),
    ('37ef8e47-67cf-5719-a5bb-7013d0d931c6'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Quel mode de vie ont les humains du Paléolithique ?', 'mcq', '["Chasseurs-cueilleurs et nomades","Agriculteurs sédentaires","Éleveurs sédentaires","Commerçants"]'::jsonb, 0, 'Ils suivent le gibier et les saisons.', 3),
    ('5acd7ff7-2feb-572b-87d8-04c8348660a1'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Quelle espèce maîtrise le feu et sort d’Afrique ?', 'mcq', '["Homo erectus","Homo habilis","Homo sapiens","Homo neanderthalensis"]'::jsonb, 0, 'Il y a environ 1,9 million d’années.', 4),
    ('71c1e841-c2cf-547d-9aff-1529c64dda0b'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Depuis combien de temps Homo sapiens existe-t-il ?', 'mcq', '["Environ 300 000 ans","Environ 3 millions d’années","Environ 40 000 ans","Environ 10 000 ans"]'::jsonb, 0, 'Notre espèce est née en Afrique.', 5),
    ('8f80acee-c700-5455-8277-9a130d2cd817'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Que prouvent les peintures de Lascaux et Chauvet ?', 'mcq', '["Une pensée symbolique","La pratique de l’agriculture","L’existence de villes","L’usage de l’écriture"]'::jsonb, 0, 'Ces humains représentaient le monde.', 6),
    ('4309adb5-2c53-566f-a092-240cec9ed8da'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Sur quoi l’historien travaille-t-il pour cette période ?', 'mcq', '["Des traces matérielles : outils, ossements, foyers, peintures","Des textes écrits","Des témoignages oraux","Des registres d’État"]'::jsonb, 0, 'L’écriture n’existe pas encore.', 7),
    ('d8be9f68-85ee-572d-9309-d201d0d758be'::uuid, '785c0c59-a4c2-528e-83d5-252ab1e84a34'::uuid, 'Le Paléolithique est la période la plus courte de l’histoire humaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est de très loin la plus longue.', 8),
    ('5a1923e7-3633-5112-b700-ab6593cbe9b8'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'Par où les humains sont-ils passés pour atteindre l’Amérique ?', 'mcq', '["Le détroit de Béring, alors émergé","L’océan Atlantique","Le détroit de Gibraltar","Le canal de Panama"]'::jsonb, 0, 'Le niveau des mers était plus bas pendant la glaciation.', 1),
    ('7fd79d65-132c-5b06-a493-7141ab49405c'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'Vers quelle date l’Australie a-t-elle été peuplée ?', 'mcq', '["Vers 50 000 ans","Vers 15 000 ans","Vers 5 000 ans","Vers 100 000 ans"]'::jsonb, 0, 'Ce peuplement supposait de naviguer.', 2),
    ('03ae8c20-f625-56c5-9712-2cab59f7c788'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'Quelle cause explique les migrations préhistoriques ?', 'mcq', '["La recherche de ressources et les variations du climat","Les guerres entre États","Le commerce","La religion"]'::jsonb, 0, 'Les groupes suivaient le gibier.', 3),
    ('70c5c572-4eb8-5122-b36d-5b0bdf8a580d'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'Sur quelle durée ces migrations se sont-elles étalées ?', 'mcq', '["Des millénaires","Quelques années","Quelques siècles","Quelques mois"]'::jsonb, 0, 'Ce sont des glissements de génération en génération.', 4),
    ('c1bb5119-55d3-584c-b476-c127b590fed8'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'Qu’a confirmé l’étude de l’ADN des populations actuelles ?', 'mcq', '["L’origine africaine et les routes du peuplement","L’existence de races biologiques","Une origine européenne","Plusieurs espèces humaines actuelles"]'::jsonb, 0, 'Les différences entre groupes humains sont très faibles.', 5),
    ('972ba45d-794d-5154-a81a-d93715070081'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'Vers quelle date Homo sapiens atteint-il l’Europe ?', 'mcq', '["Vers 45 000 ans","Vers 100 000 ans","Vers 15 000 ans","Vers 5 000 ans"]'::jsonb, 0, 'Il y côtoie Néandertal.', 6),
    ('3793659a-d119-5c6f-bcee-15dc56ba4841'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'Comment les humains se sont-ils installés dans des milieux très froids ?', 'mcq', '["Par des adaptations techniques : vêtements cousus, lampes à graisse","En hibernant","En ne s’y installant pas","Par une transformation biologique rapide"]'::jsonb, 0, 'L’adaptation technique est la marque de l’espèce.', 7),
    ('9d2e8165-6765-5073-8704-7fcd52e9009b'::uuid, '88bbc446-d25a-54d4-b6c9-30b6ee39db39'::uuid, 'L’humanité actuelle se divise en plusieurs races biologiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La génétique établit l’unité de l’espèce humaine.', 8),
    ('5046cbe2-5a22-5e59-b6f6-babb75066bd5'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Quand commence la révolution néolithique ?', 'mcq', '["Vers 10 000 av. J.-C.","Vers 3 000 av. J.-C.","Vers 100 000 av. J.-C.","Vers 500 av. J.-C."]'::jsonb, 0, 'Au Proche-Orient, dans le Croissant fertile.', 1),
    ('c35acb9e-2abd-5a0d-8161-a9fb36eda896'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Quelles sont les deux inventions majeures du Néolithique ?', 'mcq', '["L’agriculture et l’élevage","Le feu et l’outil","L’écriture et la roue","Le bronze et le fer"]'::jsonb, 0, 'On passe du prélèvement à la production.', 2),
    ('5d1c817b-cf38-554d-a613-ccc9040ba76e'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Quelle conséquence directe l’agriculture a-t-elle sur le mode de vie ?', 'mcq', '["La sédentarisation","Le nomadisme accru","La disparition des villages","La fin de l’élevage"]'::jsonb, 0, 'Il faut rester pour surveiller champs et troupeaux.', 3),
    ('71bb3e36-1497-57f4-88a2-4a9282488034'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Qu’est-ce que la domestication ?', 'mcq', '["La sélection des plantes et des animaux les plus utiles au fil des générations","L’enfermement des animaux","La construction de maisons","La cuisson des aliments"]'::jsonb, 0, 'Elle transforme durablement les espèces.', 4),
    ('33f4e4fa-41f6-5511-8238-1acac0e6c799'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Quelle conséquence sociale les surplus agricoles entraînent-ils ?', 'mcq', '["L’apparition d’inégalités et de métiers spécialisés","La disparition des chefs","L’égalité entre tous","La fin des échanges"]'::jsonb, 0, 'Ce qui se stocke peut s’accumuler.', 5),
    ('ecff71c1-447a-5cee-be91-c3d3fa43243a'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Où le Néolithique est-il apparu ?', 'mcq', '["Dans plusieurs foyers indépendants : Proche-Orient, Chine, Afrique, Amérique","Uniquement au Proche-Orient","Uniquement en Europe","Uniquement en Chine"]'::jsonb, 0, 'Ces foyers n’étaient pas en contact.', 6),
    ('3d1a2f14-c4c1-5875-9d89-2b1e3d436684'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Quels monuments témoignent des sociétés néolithiques d’Europe ?', 'mcq', '["Les dolmens et les menhirs","Les pyramides","Les temples grecs","Les cathédrales"]'::jsonb, 0, 'Carnac et Stonehenge en sont célèbres.', 7),
    ('61e8f460-ab3a-5fde-937a-65a6f48b14d9'::uuid, '448f4a60-f19a-5ad1-b0dd-39d95f8d11e2'::uuid, 'Au Néolithique, tous les habitants d’un village cultivaient la terre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les surplus permettent des métiers spécialisés.', 8),
    ('3b0ee3d6-a280-5386-adc5-f8abcff18bb6'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'Où apparaissent les premiers États ?', 'mcq', '["En Mésopotamie et en Égypte","En Grèce et à Rome","En Chine et en Inde","En Europe du Nord"]'::jsonb, 0, 'Dans les vallées du Tigre, de l’Euphrate et du Nil.', 1),
    ('bd9153ab-f14e-5a6b-9b05-d4d5a489da67'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'Vers quelle date apparaissent les premiers États ?', 'mcq', '["Vers 3500-3000 av. J.-C.","Vers 10 000 av. J.-C.","Vers 500 av. J.-C.","Vers 1000 apr. J.-C."]'::jsonb, 0, 'Environ 7 000 ans après le début du Néolithique.', 2),
    ('91f188cc-98e8-5dfc-868e-1b827da2b5af'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'Pourquoi les fleuves sont-ils décisifs ?', 'mcq', '["Ils fournissent eau, crues fertilisantes et voie de transport","Ils protègent des invasions","Ils fournissent du métal","Ils délimitent les frontières"]'::jsonb, 0, 'L’irrigation appelle une organisation collective.', 3),
    ('66c53274-8bae-54ee-a4f5-7b5452ce82fd'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'Comment appelle-t-on le temple à degrés des cités mésopotamiennes ?', 'mcq', '["La ziggurat","La pyramide","Le parthénon","Le forum"]'::jsonb, 0, 'Il domine la ville.', 4),
    ('893e0b38-101e-5cea-a35f-bb7c60af956c'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'Quel est le statut du pharaon ?', 'mcq', '["Un roi divin, maître des terres et des hommes","Un chef élu","Un grand prêtre sans pouvoir politique","Un chef de guerre temporaire"]'::jsonb, 0, 'Il unifie la Haute et la Basse-Égypte.', 5),
    ('7f859eb1-b992-5c89-88d9-d701e1f9ea9b'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'À quoi servaient les pyramides de Gizeh ?', 'mcq', '["De tombeaux royaux","De temples de culte quotidien","De greniers","De forteresses"]'::jsonb, 0, 'Elles mesurent aussi la puissance du pouvoir.', 6),
    ('12706b46-f3c2-5118-89c0-04c60c6f587f'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'Qui compose la majorité de la population dans ces premiers États ?', 'mcq', '["Les paysans et les artisans","Les scribes","Les prêtres","Les guerriers"]'::jsonb, 0, 'La société est fortement hiérarchisée.', 7),
    ('2e7edacd-95ed-5bee-8b3c-eaf03379dd58'::uuid, '18f7eb38-de14-5688-9fa7-b04ae79d282f'::uuid, 'Un État se définit par un territoire, une population et un pouvoir organisé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des lois, un impôt et des fonctionnaires.', 8),
    ('9e2d723e-a9d8-56b9-98d3-30f42b85f2ef'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Qu’est-ce qu’une cité-État ?', 'mcq', '["Une ville et son territoire, gouvernée par un roi","Un empire de plusieurs peuples","Un village agricole","Une région sans pouvoir"]'::jsonb, 0, 'Ur, Uruk et Mari en sont des exemples.', 1),
    ('9524f281-b11b-517d-8fd6-c24dfc343d5e'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Qu’est-ce qu’un empire ?', 'mcq', '["La domination d’un peuple sur de nombreux autres","Une cité indépendante","Un territoire sans roi","Une alliance de villages"]'::jsonb, 0, 'Akkad, Babylone et l’Assyrie en sont.', 2),
    ('19132443-c546-5c21-83a3-98a38c4953f4'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Vers quelle date le code de Hammurabi est-il gravé ?', 'mcq', '["Vers 1750 av. J.-C.","Vers 3000 av. J.-C.","Vers 500 av. J.-C.","Vers 1000 apr. J.-C."]'::jsonb, 0, 'Par le roi de Babylone.', 3),
    ('a6a22fe9-8b73-55a0-b745-5421c6247611'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Quel est l’apport majeur du code de Hammurabi ?', 'mcq', '["La loi est écrite et publique, donc connaissable de tous","La loi devient égalitaire","Il supprime les peines","Il abolit l’esclavage"]'::jsonb, 0, 'Les peines restent différentes selon le rang social.', 4),
    ('21d22cfc-bed1-5a25-9b82-4df21bf2f7f3'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Où le code de Hammurabi est-il gravé ?', 'mcq', '["Sur une stèle de pierre exposée publiquement","Sur des tablettes conservées au palais","Sur des papyrus","Sur les murs d’un temple fermé"]'::jsonb, 0, 'Il devait être vu de tous.', 5),
    ('4ae5c3f9-3a1e-5ac0-bc8c-180ca5077572'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Qu’est-ce que le Croissant fertile ?', 'mcq', '["Une bande de terres allant du golfe Persique à l’Égypte","Une région d’Afrique du Nord","Une vallée d’Europe","Une île de Méditerranée"]'::jsonb, 0, 'Berceau de l’agriculture et des premiers États.', 6),
    ('49b0e5d6-28ac-5b59-837e-3023a88f61bc'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Que diffusent les échanges commerciaux de ces États ?', 'mcq', '["Les techniques, les écritures et les croyances","Uniquement des marchandises","Uniquement des armes","Rien d’immatériel"]'::jsonb, 0, 'Le commerce transporte aussi des idées.', 7),
    ('bd901f19-9b42-5a66-a2b3-347a379cdac9'::uuid, 'e0ddbefd-ccd1-5275-9284-02effe74c108'::uuid, 'Les peines du code de Hammurabi sont les mêmes pour tous.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles varient selon le rang social.', 8),
    ('68059cb4-b9ff-5ec4-bb03-237dea9a5181'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Vers quelle date l’écriture apparaît-elle ?', 'mcq', '["Vers 3300 av. J.-C.","Vers 10 000 av. J.-C.","Vers 1200 av. J.-C.","Vers 500 apr. J.-C."]'::jsonb, 0, 'En Mésopotamie.', 1),
    ('6c2f537a-4320-5637-a151-7dbbace1ad24'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Quel événement marque le passage de la Préhistoire à l’Histoire ?', 'mcq', '["L’invention de l’écriture","L’invention de l’agriculture","La maîtrise du feu","La naissance des villes"]'::jsonb, 0, 'Les sociétés laissent alors des textes.', 2),
    ('28606fe1-0b37-5185-b8c6-2f41e5fbd59d'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Pourquoi l’écriture a-t-elle été inventée ?', 'mcq', '["Pour tenir des comptes et administrer","Pour écrire des poèmes","Pour écrire des lois religieuses","Pour envoyer des lettres"]'::jsonb, 0, 'Les premières tablettes sont des comptes.', 3),
    ('6051fb07-81dc-5dd9-a4e0-49b0cc8b1c98'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Sur quel support écrit-on le cunéiforme ?', 'mcq', '["Sur des tablettes d’argile","Sur du papyrus","Sur du parchemin","Sur de la pierre uniquement"]'::jsonb, 0, 'Avec un calame, un roseau taillé.', 4),
    ('98951c9c-98b7-568f-88c5-0f682cdc7dfa'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Qui a déchiffré les hiéroglyphes, et quand ?', 'mcq', '["Champollion, en 1822","Hammurabi, en 1750 av. J.-C.","Hérodote, au Ve siècle av. J.-C.","Sargon, en 2300 av. J.-C."]'::jsonb, 0, 'Grâce à la pierre de Rosette.', 5),
    ('01c24b8a-12e5-537b-a04b-b34ba853966a'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Quel peuple met au point le premier alphabet ?', 'mcq', '["Les Phéniciens","Les Égyptiens","Les Grecs","Les Romains"]'::jsonb, 0, 'Les Grecs y ajouteront les voyelles.', 6),
    ('77abb53e-fbe8-5c3c-8587-d341fecc0767'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Quel est l’avantage de l’alphabet sur le cunéiforme ?', 'mcq', '["Une vingtaine de signes au lieu de plusieurs centaines","Il est plus beau","Il s’écrit plus vite sur l’argile","Il note davantage de mots"]'::jsonb, 0, 'Il met l’écriture à la portée de bien plus de gens.', 7),
    ('4e73d4e6-2ddb-567d-8352-e7f81d939e6a'::uuid, '5fbda21c-0ef5-5e07-a7de-70fbc93f9da9'::uuid, 'Dans ces sociétés, savoir écrire était courant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’était le métier des scribes, une position sociale élevée.', 8),
    ('7458fb3d-8ed6-5116-83f9-6e219f2531d7'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'Comment appelle-t-on une cité grecque ?', 'mcq', '["Une polis","Une civitas","Une agora","Une acropole"]'::jsonb, 0, 'Le mot « politique » en vient.', 1),
    ('e0803082-2dab-525e-8dde-4595317ed5f0'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'Qu’est-ce que l’agora ?', 'mcq', '["La place publique, marché et lieu de débat","Le temple principal","La ville haute","Le port"]'::jsonb, 0, 'L’acropole est la ville haute.', 2),
    ('044214b4-6f84-5024-b776-027fe6c0dc6c'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'Quelles œuvres sont attribuées à Homère ?', 'mcq', '["L’Iliade et l’Odyssée","La Théogonie","Les Fables","L’Énéide"]'::jsonb, 0, 'Ce sont les récits fondateurs communs aux Grecs.', 3),
    ('48fe60eb-6f06-5677-afe4-28f9dc7ce280'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'En quelle année la tradition situe-t-elle les premiers Jeux olympiques ?', 'mcq', '["776 av. J.-C.","1200 av. J.-C.","508 av. J.-C.","146 av. J.-C."]'::jsonb, 0, 'Ils réunissaient toutes les cités.', 4),
    ('0204a4bc-c3d1-51ca-aa8a-7c729765208d'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'Comment les Grecs s’appellent-ils eux-mêmes ?', 'mcq', '["Les Hellènes","Les Barbares","Les Latins","Les Achéens seulement"]'::jsonb, 0, 'Ils nomment Barbares ceux qui ne parlent pas leur langue.', 5),
    ('c8b760d8-8f62-5e27-8005-234120cad453'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'Quelle cité les Grecs ont-ils fondée vers 600 av. J.-C. en Gaule ?', 'mcq', '["Massalia (Marseille)","Lutèce","Alexandrie","Byzance"]'::jsonb, 0, 'C’est une colonie de la cité de Phocée.', 6),
    ('8b2f905e-64ae-534f-bc84-fdd0d213d370'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'Pourquoi les Grecs fondent-ils des colonies ?', 'mcq', '["Par manque de terres dans leurs cités","Pour fuir une invasion","Pour convertir d’autres peuples","Par ordre d’un roi unique"]'::jsonb, 0, 'Elles gardent des liens avec la cité mère.', 7),
    ('9bc43b83-0811-5b89-b9b4-b67e5cb24627'::uuid, 'd071e936-450d-5c1d-8346-18019034f45d'::uuid, 'La Grèce antique formait un État unifié.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’était une multitude de cités indépendantes.', 8),
    ('259802a9-d952-5093-8e9c-41f3047dc889'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'Où siègent les principaux dieux grecs ?', 'mcq', '["Sur le mont Olympe","À Delphes","Sur l’Acropole","Aux Enfers"]'::jsonb, 0, 'Ils sont douze.', 1),
    ('8707698f-d1a2-58e7-800c-706a823f9f18'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'Quelle déesse protège la cité d’Athènes ?', 'mcq', '["Athéna","Héra","Aphrodite","Artémis"]'::jsonb, 0, 'Le Parthénon lui est consacré.', 2),
    ('8162968c-471a-5253-8383-fa95188f63d1'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'Que signifie « dieux anthropomorphes » ?', 'mcq', '["Ils ont une forme et des sentiments humains","Ils sont invisibles","Ils sont parfaits moralement","Ils vivent parmi les hommes"]'::jsonb, 0, 'Ils diffèrent par l’immortalité, pas par la vertu.', 3),
    ('75b5d602-5761-51b6-8ed2-549677ed48af'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'À quoi sert un temple grec ?', 'mcq', '["Il abrite la statue du dieu ; les cérémonies ont lieu dehors","Il rassemble les fidèles à l’intérieur","Il sert d’école","Il sert de marché"]'::jsonb, 0, 'C’est la maison du dieu.', 4),
    ('21a3aeef-6c14-56da-9770-16331e8630d5'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'Qui rend les oracles à Delphes ?', 'mcq', '["La Pythie, au nom d’Apollon","Le grand prêtre de Zeus","Un roi","Un devin itinérant"]'::jsonb, 0, 'On la consultait avant toute grande décision.', 5),
    ('4780688e-68ce-5c25-87e2-3658bfc7859f'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'Qu’est-ce qu’un héros dans la religion grecque ?', 'mcq', '["Un être entre dieux et hommes, accomplissant des exploits","Un prêtre","Un soldat courageux ordinaire","Un roi"]'::jsonb, 0, 'Héraclès, Thésée, Achille, Ulysse.', 6),
    ('148d51f0-ce8f-5edf-8a7d-76c7c6bbcff2'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'En l’honneur de quel dieu se déroulent les Jeux olympiques ?', 'mcq', '["Zeus","Apollon","Dionysos","Poséidon"]'::jsonb, 0, 'Une trêve sacrée les accompagne.', 7),
    ('5a94bc23-c137-554f-96f4-be4872a31ee9'::uuid, '8bd04912-f58e-5555-af24-990e1481fa18'::uuid, 'Le théâtre grec était une activité purement profane.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il naît des fêtes de Dionysos : c’est un acte religieux et civique.', 8),
    ('83af45d2-1606-59a9-81aa-9cdab8daa75a'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'Que signifie le mot « démocratie » ?', 'mcq', '["Le pouvoir du peuple","Le pouvoir des riches","Le pouvoir d’un seul","Le pouvoir des prêtres"]'::jsonb, 0, 'De dêmos, le peuple, et kratos, le pouvoir.', 1),
    ('e75f870e-f5d9-5e9a-bf38-6964c41329d2'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'Quelle date marque l’acte de naissance de la démocratie athénienne ?', 'mcq', '["508 av. J.-C., les réformes de Clisthène","594 av. J.-C.","776 av. J.-C.","146 av. J.-C."]'::jsonb, 0, 'Solon l’avait préparée, Périclès l’a portée à son apogée.', 2),
    ('02d8be59-e3d9-55df-b710-ca639721e0b2'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'Qu’est-ce que l’Ecclésia ?', 'mcq', '["L’assemblée de tous les citoyens","Le conseil de 500 membres","Le tribunal populaire","Le collège des stratèges"]'::jsonb, 0, 'Elle se réunit sur la Pnyx.', 3),
    ('43b5f3e6-d898-5dcc-9dd5-7e4a3703a678'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'Combien de citoyens composent la Boulè ?', 'mcq', '["500, tirés au sort","6 000, élus","10, élus","40 000"]'::jsonb, 0, 'Elle prépare les débats de l’Ecclésia.', 4),
    ('cbb8f6db-a1fe-5c2b-a30d-40c13b88a06f'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'Pourquoi les Athéniens préfèrent-ils le tirage au sort à l’élection ?', 'mcq', '["Le tirage au sort réalise l’égalité, l’élection favorise les notables","Il est plus rapide","Il coûte moins cher","Il était imposé par les dieux"]'::jsonb, 0, 'Seuls les stratèges sont élus.', 5),
    ('14459d97-a9b9-518a-88b9-d87cbb62b3dc'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'Qu’est-ce que l’ostracisme ?', 'mcq', '["Le bannissement pour dix ans d’un citoyen jugé dangereux","Une amende","Une charge publique","Un impôt"]'::jsonb, 0, 'On écrivait le nom sur un tesson de poterie.', 6),
    ('766703fc-9f48-5014-9cdc-a6050a26b167'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'Qui est exclu de la citoyenneté à Athènes ?', 'mcq', '["Les femmes, les métèques et les esclaves","Seulement les esclaves","Seulement les étrangers","Personne"]'::jsonb, 0, '40 000 citoyens sur 300 000 habitants.', 7),
    ('d2a6cd21-9543-5942-962a-94cdb51f86dd'::uuid, '311304de-2446-59f0-8a71-db459514ac64'::uuid, 'La démocratie athénienne concernait toute la population.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Environ un habitant sur sept était citoyen.', 8),
    ('b9b47a37-12eb-50f4-ad5a-81d72875ed09'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'Qui peut être citoyen à Athènes après 451 av. J.-C. ?', 'mcq', '["Un homme de plus de 18 ans né de père citoyen et de mère fille de citoyen","Tout homme libre","Tout habitant de la cité","Tout homme payant l’impôt"]'::jsonb, 0, 'C’est la loi de Périclès.', 1),
    ('f9946813-1977-51cf-8a74-e481f54ab698'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'Qui sont les métèques ?', 'mcq', '["Des étrangers libres installés à Athènes","Des esclaves affranchis","Des citoyens pauvres","Des prêtres"]'::jsonb, 0, 'Ils paient un impôt mais ne sont jamais citoyens.', 2),
    ('dd32799b-8fc8-5478-913a-70fd393420b1'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'Quelle proportion de la population les esclaves représentent-ils ?', 'mcq', '["Environ la moitié","Environ un dixième","Environ un quart","Une infime minorité"]'::jsonb, 0, 'Ils sont juridiquement des biens.', 3),
    ('f1dbd19f-8098-5bed-939a-2049f2ce0d51'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'Qu’est-ce que l’éphébie ?', 'mcq', '["Deux ans de service militaire pour les jeunes citoyens","Une fête religieuse","Un impôt","Un tribunal"]'::jsonb, 0, 'Elle s’achève par un serment de défendre la cité.', 4),
    ('fa007faf-beae-547e-9644-656a230bcaca'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'Quel est le statut des femmes à Athènes ?', 'mcq', '["Libres, mais sans droits politiques","Citoyennes à part entière","Esclaves","Métèques"]'::jsonb, 0, 'Elles vivent sous l’autorité d’un tuteur.', 5),
    ('a27f6758-4a1b-5acb-85ea-9443b2765dc5'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'Qu’est-ce qu’une liturgie ?', 'mcq', '["L’obligation faite aux plus riches de financer une trière ou un chœur","Une cérémonie religieuse quotidienne","Un vote à l’assemblée","Une peine judiciaire"]'::jsonb, 0, 'C’est un devoir civique des grandes fortunes.', 6),
    ('81109e5b-cfc8-5fe3-b264-c62811e073d1'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'Quelle grande fête rassemble la cité en l’honneur d’Athéna ?', 'mcq', '["Les Panathénées","Les Jeux olympiques","Les Dionysies seules","L’Ecclésia"]'::jsonb, 0, 'La procession met en scène l’ordre social.', 7),
    ('fe621e2d-92a0-5fb3-8936-c3c8739e756f'::uuid, 'd92664f8-aaeb-5f4f-846f-37c3390e9cc4'::uuid, 'La démocratie athénienne était représentative, comme la nôtre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle était directe : les citoyens votaient eux-mêmes les lois.', 8),
    ('107bde80-e48f-50d4-b3ff-27ca67ee7b05'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Quelle date la légende donne-t-elle à la fondation de Rome ?', 'mcq', '["753 av. J.-C.","509 av. J.-C.","27 av. J.-C.","476 apr. J.-C."]'::jsonb, 0, 'Romulus en serait le fondateur.', 1),
    ('8d268213-a7c9-59ec-a517-047c45e921c6'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Qui aurait allaité Romulus et Rémus ?', 'mcq', '["Une louve","Une chèvre","Une bergère","Une déesse"]'::jsonb, 0, 'Ils sont fils du dieu Mars.', 2),
    ('d2612f84-5eb0-542a-ad76-466616e21f1d'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Quel héros troyen Virgile donne-t-il pour ancêtre aux Romains ?', 'mcq', '["Énée","Ulysse","Achille","Hector"]'::jsonb, 0, 'Dans l’Énéide, au Ier siècle av. J.-C.', 3),
    ('b7987277-72dd-5a15-ada1-a0e089ff7a0a'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Que montre l’archéologie du Palatin ?', 'mcq', '["Des cabanes de bergers dès le VIIIe siècle av. J.-C.","Une grande ville fondée d’un coup","Aucune trace avant le Ier siècle","Un camp militaire grec"]'::jsonb, 0, 'Rome se forme progressivement.', 4),
    ('5a6ebe6b-2c03-51c6-af02-f9462e050cd2'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Quel peuple a fortement influencé les débuts de Rome ?', 'mcq', '["Les Étrusques","Les Égyptiens","Les Perses","Les Carthaginois"]'::jsonb, 0, 'Rome leur emprunte techniques et insignes du pouvoir.', 5),
    ('e18043c0-fba6-5790-9dda-cc7bd592a1e2'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Quelles sont les trois grandes périodes de l’histoire romaine ?', 'mcq', '["Royauté, République, Empire","Empire, République, Royauté","Royauté, Empire, République","République, Royauté, Empire"]'::jsonb, 0, 'La République commence en 509 av. J.-C.', 6),
    ('ce8239d9-b2c3-5b4e-9cfe-cd6a6715de1f'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Pourquoi les récits fondateurs sont-ils écrits sept siècles après les faits ?', 'mcq', '["Rome domine alors la Méditerranée et veut justifier cette domination","Les auteurs manquaient de sources","L’écriture n’existait pas avant","Par hasard"]'::jsonb, 0, 'Le récit dit ce que Rome veut être.', 7),
    ('4e542ff1-8ef4-5ea6-872e-6c2fd2006725'::uuid, 'bc1039a1-fe4f-5671-afad-ba7c3e3cbc48'::uuid, 'Les récits de Virgile et de Tite-Live sont des comptes rendus fidèles des faits.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils disent les croyances de leur époque, non ce qui s’est passé.', 8),
    ('edfe1d6a-b984-5b3b-abad-0847b2a6226e'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'Qu’étudie l’archéologie ?', 'mcq', '["Les traces matérielles laissées par les sociétés","Uniquement les textes anciens","Les langues anciennes","Les traditions orales"]'::jsonb, 0, 'Murs, tombes, poteries, ossements, outils.', 1),
    ('2e74bc60-fd5f-5020-b90d-5fb9117f94b8'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'Qu’est-ce que la stratigraphie ?', 'mcq', '["L’étude des couches du sol, les plus profondes étant les plus anciennes","La datation par le carbone 14","L’étude des monnaies","Le dessin des objets trouvés"]'::jsonb, 0, 'Elle donne une chronologie relative.', 2),
    ('a06a6d61-638f-52cf-9d08-073cdea1457c'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'Pourquoi note-t-on précisément la position de chaque objet ?', 'mcq', '["Le contexte donne le sens, plus que l’objet lui-même","Pour le retrouver plus tard","Pour le vendre","Pour le nettoyer"]'::jsonb, 0, 'Un objet hors de sa couche perd son intérêt scientifique.', 3),
    ('d0307041-0a88-5ee8-8bcf-7b34a5e070e3'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'Quelle méthode date les matières organiques ?', 'mcq', '["Le carbone 14","La stratigraphie","La dendrochronologie des monnaies","La comparaison des styles"]'::jsonb, 0, 'C’est une datation absolue.', 4),
    ('7c6b3ca1-844e-59df-b759-6c840b71ed11'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'Qu’a-t-on trouvé sur le Palatin ?', 'mcq', '["Des trous de poteaux de cabanes du VIIIe siècle av. J.-C.","Un palais royal","Un temple grec","Rien avant le Ier siècle"]'::jsonb, 0, 'La date légendaire n’est donc pas absurde.', 5),
    ('bcb4ae83-5a3f-5fd7-bfd4-6c30a33c021f'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'Que montrent les importations grecques et étrusques trouvées à Rome ?', 'mcq', '["Des échanges précoces avec d’autres peuples","Une conquête étrangère","Une famine","L’absence de commerce"]'::jsonb, 0, 'Rome n’était pas isolée.', 6),
    ('be134684-01b0-51f2-93d6-f8cae94e2d4f'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'Comment l’archéologie décrit-elle la naissance de Rome ?', 'mcq', '["Comme un processus de regroupement de villages","Comme une fondation en un seul jour","Comme une colonie grecque","Comme une invention tardive"]'::jsonb, 0, 'Elle déplace la question plutôt que de trancher la légende.', 7),
    ('d94c7116-58fe-51c2-bf34-050f085b357a'::uuid, '3590999d-2b0f-5bb8-b52e-7992c3ac0150'::uuid, 'L’archéologie a prouvé que Romulus avait bien fondé Rome en 753 av. J.-C.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne confirme ni n’infirme la légende : elle décrit un processus.', 8),
    ('e0902f15-488a-50a4-a321-e6fbc4be5bfc'::uuid, '5ef517bb-f9da-5c56-a17a-47e9da586a5e'::uuid, 'En quelle année la République romaine est-elle fondée ?', 'mcq', '["509 av. J.-C.","753 av. J.-C.","27 av. J.-C.","44 av. J.-C."]'::jsonb, 0, 'Les Romains chassent leur dernier roi.', 1),
    ('987290f6-d736-516a-b44d-26332e61d263'::uuid, '5ef517bb-f9da-5c56-a17a-47e9da586a5e'::uuid, 'Que signifie SPQR ?', 'mcq', '["Le Sénat et le peuple romain","La République romaine unie","Rome, reine du monde","Le pouvoir du peuple"]'::jsonb, 0, 'Senatus PopulusQue Romanus.', 2),
