    ('30c94268-6c65-5608-b10a-ac8770093f11'::uuid, '5ef517bb-f9da-5c56-a17a-47e9da586a5e'::uuid, 'Quelle est la durée d’une magistrature romaine ?', 'mcq', '["Un an","Cinq ans","À vie","Dix ans"]'::jsonb, 0, 'La brièveté limite les abus.', 4),
    ('0b32c284-b020-59f7-aa9e-20e8109cd9d2'::uuid, '5ef517bb-f9da-5c56-a17a-47e9da586a5e'::uuid, 'Qui compose le Sénat ?', 'mcq', '["Environ 300 anciens magistrats nommés à vie","Des citoyens tirés au sort","Les tribuns de la plèbe","Des représentants élus chaque année"]'::jsonb, 0, 'Il dirige en fait la politique étrangère et les finances.', 5),
    ('5b1150d5-25e1-5216-b51f-c4c35c05bbc1'::uuid, '5ef517bb-f9da-5c56-a17a-47e9da586a5e'::uuid, 'Quel droit les tribuns de la plèbe obtiennent-ils ?', 'mcq', '["Le droit de veto","Le commandement de l’armée","La nomination des sénateurs","La levée de l’impôt"]'::jsonb, 0, '« Veto » signifie « je m’oppose ».', 6),
