    ('07789b44-79c6-5ae2-8ac7-8a98616ea69d'::uuid, '5ef517bb-f9da-5c56-a17a-47e9da586a5e'::uuid, 'La République romaine accordait un vote de poids égal à chaque citoyen.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le vote se faisait par groupes pondérés selon la richesse.', 8),
