    ('2219679e-a97f-50b5-b391-107fb40be4dc'::uuid, 'bd5d3cbd-066c-5291-97c7-4b9d83192d8e'::uuid, 'Qui César bat-il à Alésia en 52 av. J.-C. ?', 'mcq', '["Vercingétorix","Hannibal","Spartacus","Pompée"]'::jsonb, 0, 'C’est l’achèvement de la conquête de la Gaule.', 3),
