    ('d1150473-4814-5b52-b27f-7515c8cea14a'::uuid, '694d390e-43c1-5d9f-9a64-78bc36db24af'::uuid, 'Quelles sources non chrétiennes mentionnent les premiers chrétiens ?', 'mcq', '["Flavius Josèphe, Tacite et Suétone","Les Évangiles","Virgile et Tite-Live","Homère"]'::jsonb, 0, 'Elles confirment l’existence du mouvement.', 5),
