    ('27bb94d2-dd9b-5f8e-8a97-d349580b2732'::uuid, '32d0cc50-ac5d-57f8-9f4c-6b0a73f01e3e'::uuid, 'Quel concile Constantin convoque-t-il en 325 ?', 'mcq', '["Le concile de Nicée","Le concile de Milan","Le concile de Rome","Le concile de Thessalonique"]'::jsonb, 0, 'Les conciles fixent la doctrine.', 7),
