    ('c61ac604-248b-5ad2-9eb7-77395fb4b187'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Quelles sont les dates de la dynastie Han ?', 'mcq', '["206 av. J.-C. - 220 apr. J.-C.","221-206 av. J.-C.","27 av. J.-C. - 476 apr. J.-C.","509-27 av. J.-C."]'::jsonb, 0, 'Elle est contemporaine de Rome.', 1),
    ('d6432eaf-9cff-5c0e-9d72-79068d8cb014'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Qui unifie la Chine en 221 av. J.-C. ?', 'mcq', '["Qin Shi Huangdi","Confucius","Un empereur Han","Trajan"]'::jsonb, 0, 'Il se fait enterrer avec une armée de terre cuite.', 2),
    ('fdce14af-6551-55d6-8377-b8c4e8256e79'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Comment appelle-t-on l’empereur chinois ?', 'mcq', '["Le Fils du Ciel","Le Grand Pontife","L’Imperator","Le Roi des rois"]'::jsonb, 0, 'Il détient le mandat céleste.', 3),
    ('9ee4742f-7b71-526c-99ae-eebde911414c'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Comment les fonctionnaires chinois sont-ils recrutés ?', 'mcq', '["Sur concours","Par naissance","Par tirage au sort","Par élection"]'::jsonb, 0, 'C’est une invention sans équivalent à Rome.', 4),
    ('506fabc3-9958-50b7-9127-aa36d9b78475'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Quelle invention majeure les Han mettent-ils au point vers 105 apr. J.-C. ?', 'mcq', '["Le papier","La poudre","L’imprimerie","Le verre"]'::jsonb, 0, 'Elle mettra des siècles à parvenir en Occident.', 5),
    ('2cf2d49b-02e9-58d9-b76d-ed3d2b6d76fc'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Qu’est-ce que la route de la soie ?', 'mcq', '["Un réseau de pistes caravanières reliant la Chine à la Méditerranée","Une route maritime","Une voie romaine","Un fleuve navigable"]'::jsonb, 0, 'Y circulent marchandises, religions, techniques et épidémies.', 6),
    ('59944a16-f854-5361-b1d1-4300de1d6d1b'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Quelle pensée structure l’État chinois des Han ?', 'mcq', '["Le confucianisme","Le stoïcisme","Le christianisme","Le bouddhisme uniquement"]'::jsonb, 0, 'Ordre social, respect des aînés, devoir.', 7),
    ('1e2075d4-12ae-5965-937f-2580d6d12d90'::uuid, '63248e24-9ad7-53c1-9f8b-f93137b59cc2'::uuid, 'Rome et la Chine des Han entretenaient des relations directes et régulières.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les contacts directs étaient rarissimes : chacun connaissait l’autre par ouï-dire.', 8),
    ('ee864780-8bc8-5575-85d9-83a5bddea6d6'::uuid, 'ff8dc7fd-8b46-5733-8150-7bdf91e044d8'::uuid, 'Qu’est-ce qu’une métropole ?', 'mcq', '["Une grande ville qui concentre les fonctions de commandement","Une ville de plus de 10 000 habitants","Une capitale d’État","Une ville industrielle"]'::jsonb, 0, 'Elle rayonne bien au-delà de ses limites.', 1),
    ('f079fa8a-6c16-57a8-9374-c22cd63c8e27'::uuid, 'ff8dc7fd-8b46-5733-8150-7bdf91e044d8'::uuid, 'Depuis quelle année plus de la moitié de l’humanité vit-elle en ville ?', 'mcq', '["2007","1950","1990","2020"]'::jsonb, 0, 'La proportion approche 60 % aujourd’hui.', 2),
    ('476f7cc0-a390-56ad-8562-6c566e2d65b5'::uuid, 'ff8dc7fd-8b46-5733-8150-7bdf91e044d8'::uuid, 'Qu’est-ce qu’une mégapole ?', 'mcq', '["Une agglomération de plus de 10 millions d’habitants","Une capitale politique","Une ville de plus d’un million d’habitants","Une ville mondiale"]'::jsonb, 0, 'On en compte plus de trente.', 3),
    ('5fb9436b-ab80-5d80-bf95-04cb7a3f7da2'::uuid, 'ff8dc7fd-8b46-5733-8150-7bdf91e044d8'::uuid, 'Qu’est-ce que le CBD d’une métropole ?', 'mcq', '["Le quartier d’affaires","Le centre historique","La banlieue résidentielle","La zone industrielle"]'::jsonb, 0, 'La Défense et Manhattan en sont des exemples.', 4),
    ('81009abc-46bf-59ee-8fb2-38a34cb6246c'::uuid, 'ff8dc7fd-8b46-5733-8150-7bdf91e044d8'::uuid, 'Que sont les migrations pendulaires ?', 'mcq', '["Les navettes quotidiennes domicile-travail","Les déménagements définitifs","Les migrations internationales","Les départs en vacances"]'::jsonb, 0, 'Elles saturent les transports aux heures de pointe.', 5),
    ('66bf80cd-b8ab-5bfe-b037-8231647609eb'::uuid, 'ff8dc7fd-8b46-5733-8150-7bdf91e044d8'::uuid, 'Comment appelle-t-on les bidonvilles à Rio de Janeiro ?', 'mcq', '["Les favelas","Les slums","Les townships","Les barrios"]'::jsonb, 0, 'On dit slums à Mumbai.', 6),
