    ('24cbe46e-844a-56f2-a189-e15aa64a3097'::uuid, 'ff8dc7fd-8b46-5733-8150-7bdf91e044d8'::uuid, 'Une métropole est un espace socialement homogène.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quartiers très riches et très pauvres y coexistent.', 8),
    ('4f7b5b17-ed5c-5e0c-a13f-a91fb4a21d9d'::uuid, '2c158090-a618-5691-bba8-3c676cb5c1b4'::uuid, 'Où la croissance urbaine est-elle la plus rapide ?', 'mcq', '["Dans les pays en développement","Dans les pays développés","Partout au même rythme","Nulle part, elle ralentit"]'::jsonb, 0, 'Lagos est passée de 300 000 à plus de 15 millions d’habitants.', 1),
    ('4ae4837a-b853-5bd1-aeaf-d7018158049c'::uuid, '2c158090-a618-5691-bba8-3c676cb5c1b4'::uuid, 'Combien de personnes vivent dans des bidonvilles dans le monde ?', 'mcq', '["Environ un milliard","Environ 100 millions","Environ 10 millions","Environ 3 milliards"]'::jsonb, 0, 'Habitat auto-construit, sans titre de propriété.', 2),
    ('24aa8fbc-5159-53f0-b29f-724126288bc0'::uuid, '2c158090-a618-5691-bba8-3c676cb5c1b4'::uuid, 'Qu’est-ce que l’îlot de chaleur urbain ?', 'mcq', '["La ville est plus chaude que la campagne voisine à cause du béton et de l’asphalte","Une zone industrielle","Un quartier chauffé collectivement","Un parc urbain"]'::jsonb, 0, 'C’est un enjeu croissant avec le réchauffement.', 3),
    ('7ab5142f-114a-583a-aa0e-ca1a32b3ef26'::uuid, '2c158090-a618-5691-bba8-3c676cb5c1b4'::uuid, 'Qu’est-ce que l’étalement urbain ?', 'mcq', '["L’extension de la ville sur les terres agricoles et naturelles","La construction en hauteur","La densification du centre","La rénovation des quartiers"]'::jsonb, 0, 'Il consomme des espaces non urbanisés.', 4),
    ('182f8871-4457-52dd-9be0-d0a35f232b10'::uuid, '2c158090-a618-5691-bba8-3c676cb5c1b4'::uuid, 'Quelle réponse apporte-t-on au défi des transports ?', 'mcq', '["Métro, tramway, bus en site propre et pistes cyclables","Élargir toutes les routes","Interdire la ville aux habitants","Supprimer les transports publics"]'::jsonb, 0, 'Le télétravail et les péages urbains y contribuent aussi.', 5),
