    ('118e1dc8-d769-5dd2-964a-4c23b89eb21a'::uuid, '93b8a23b-7db8-5ffe-a518-4c6f0f271e1a'::uuid, 'Qu’est-ce que l’exode rural ?', 'mcq', '["Le départ des habitants des campagnes vers les villes","L’arrivée de citadins à la campagne","Le déplacement des troupeaux","Le tourisme rural"]'::jsonb, 0, 'Il touche surtout les campagnes éloignées.', 3),
    ('03409716-06bd-536b-8fe0-7288bdb7203e'::uuid, '93b8a23b-7db8-5ffe-a518-4c6f0f271e1a'::uuid, 'Qu’appelle-t-on un « désert médical » ?', 'mcq', '["Un espace où l’accès aux soins est très difficile","Un désert sans végétation","Un hôpital fermé","Une zone sans pharmacie uniquement"]'::jsonb, 0, 'C’est une difficulté majeure des espaces peu denses.', 4),
