    ('31f25b64-5d46-5b72-9f5a-93b0045f1a45'::uuid, '93b8a23b-7db8-5ffe-a518-4c6f0f271e1a'::uuid, 'Quelle nouvelle fonction les espaces ruraux assurent-ils ?', 'mcq', '["Résidentielle, touristique et productrice d’énergie","Uniquement agricole","Uniquement industrielle","Aucune fonction nouvelle"]'::jsonb, 0, 'Éolien, solaire et méthanisation s’y développent.', 6),
    ('cfb96162-dfac-559a-a149-f2c1310d9573'::uuid, '93b8a23b-7db8-5ffe-a518-4c6f0f271e1a'::uuid, 'Quelle contrainte pèse fortement sur les habitants des campagnes peu denses ?', 'mcq', '["La dépendance à la voiture","L’excès de transports collectifs","La densité trop forte","Le coût du logement"]'::jsonb, 0, 'Les transports collectifs y sont rares.', 7),
