    ('44f3451a-f47f-5a41-8e28-7133b6e36ca7'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Quelle part de l’humanité vit à moins de 100 km d’une côte ?', 'mcq', '["Environ 60 %","Environ 20 %","Environ 90 %","Environ 40 %"]'::jsonb, 0, 'C’est le processus de littoralisation.', 1),
    ('195c2366-aa51-51b1-9803-a00d3b977dfc'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Qu’est-ce qu’une ZIP ?', 'mcq', '["Une zone industrialo-portuaire","Une zone d’intérêt paysager","Une zone interdite à la pêche","Une zone d’implantation piscicole"]'::jsonb, 0, 'Ports en eau profonde, terminaux, raffineries.', 2),
    ('19903af5-21b5-569a-b57b-9ea736937539'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Quel est le premier port mondial ?', 'mcq', '["Shanghai","Rotterdam","Le Havre","Singapour"]'::jsonb, 0, 'Rotterdam est le premier port européen.', 3),
    ('2a70413f-f319-57b8-960d-011cdf8caf20'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Quelle part des marchandises mondiales voyage par la mer ?', 'mcq', '["Environ 80 %","Environ 30 %","Environ 50 %","Environ 10 %"]'::jsonb, 0, 'Les ports sont les nœuds de la mondialisation.', 4),
    ('ebf89432-e295-51e7-b49c-5673ffa80b8b'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Quel est un inconvénient du littoral touristique ?', 'mcq', '["Des emplois saisonniers et une bétonisation du rivage","L’absence totale d’emplois","Une baisse de la population","La disparition des ports"]'::jsonb, 0, 'L’aménagement transforme durablement la côte.', 5),
    ('7578231e-9d6b-5e4f-9289-8693d51325cb'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Quelle menace pèse sur les littoraux du fait du changement climatique ?', 'mcq', '["La montée du niveau de la mer","Le refroidissement des eaux","L’assèchement des océans","La baisse du tourisme"]'::jsonb, 0, 'Elle menace des dizaines de millions de personnes.', 6),
    ('0d2f3b5b-753a-5d32-a15c-7536f1d171de'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Quel milieu protège naturellement les côtes tropicales des tempêtes ?', 'mcq', '["La mangrove","La plage de sable nue","Le port","La marina"]'::jsonb, 0, 'Sa restauration est un moyen de protection efficace.', 7),
    ('65f86065-3c0b-5c03-b514-630be20c2841'::uuid, 'cf51dc0b-0f4c-53ab-82dc-c55aa94d0914'::uuid, 'Les différents usages du littoral se répartissent sans se concurrencer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils se disputent un espace étroit : c’est l’enjeu principal.', 8),
    ('62cff4d0-8e5b-530c-8fda-5e14a0a1e98d'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'Combien la Terre compte-t-elle d’habitants ?', 'mcq', '["Environ 8 milliards","Environ 5 milliards","Environ 10 milliards","Environ 1 milliard"]'::jsonb, 0, 'Ils sont très inégalement répartis.', 1),
    ('2d8b4d7c-b690-5eeb-a909-de04a9b48b03'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'Qu’est-ce que l’écoumène ?', 'mcq', '["La partie de la Terre habitée en permanence","L’ensemble des terres émergées","Les zones urbaines","Les déserts humains"]'::jsonb, 0, 'Il ne couvre qu’une fraction des terres émergées.', 2),
    ('10f44700-cca7-5c3c-8710-e3caa1c4a6a6'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'Quels sont les trois grands foyers de peuplement ?', 'mcq', '["Asie du Sud, Asie de l’Est et Europe","Amérique du Nord, Europe et Afrique","Afrique, Asie et Océanie","Amérique du Sud, Europe et Asie"]'::jsonb, 0, 'Ils rassemblent plus de la moitié de l’humanité.', 3),
    ('e1d6bb79-a34e-5ff4-9070-1201b125f5bf'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'Qu’est-ce qu’un désert humain ?', 'mcq', '["Un espace très peu peuplé","Un espace sans végétation","Un espace sans eau","Un espace protégé"]'::jsonb, 0, 'Déserts chauds et froids, hautes montagnes, forêts denses.', 4),
    ('3601d143-0404-5ed6-ac0c-6c3577da6cb0'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'Quel facteur naturel favorise le peuplement ?', 'mcq', '["Un climat tempéré et de l’eau disponible","Un relief très accidenté","Un froid extrême","Une forêt dense"]'::jsonb, 0, 'Sols fertiles et proximité de la mer y contribuent aussi.', 5),
    ('87440cd3-a3b2-5f59-a801-1ac3e0b758ff'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'Que faut-il toujours lire sur une carte de densité ?', 'mcq', '["La légende, car les seuils varient d’une carte à l’autre","Uniquement les couleurs","Uniquement le titre","Le nom des pays"]'::jsonb, 0, 'Deux cartes semblables peuvent utiliser des seuils différents.', 6),
    ('7dd6c522-c538-5116-bdc0-a7594b33d52e'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'Pourquoi la vallée du Nil est-elle si densément peuplée ?', 'mcq', '["Pour des raisons naturelles et historiques anciennes","Uniquement à cause du tourisme","À cause de l’industrie récente","Par hasard"]'::jsonb, 0, 'Elle est peuplée depuis 5 000 ans.', 7),
    ('fcc72973-348f-52ae-b4b8-3ddda6bfa987'::uuid, 'fe5f379e-ead4-5158-bb75-70c6df42d497'::uuid, 'La population mondiale est répartie de façon à peu près régulière sur les terres émergées.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La répartition est très inégale : foyers denses et déserts humains.', 8),
    ('fa07ab1a-beae-5465-b7b4-c12ecc4a9f72'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Comment calcule-t-on l’accroissement naturel ?', 'mcq', '["Natalité − mortalité","Entrées − sorties","Natalité + mortalité","Population totale ÷ superficie"]'::jsonb, 0, 'Le solde migratoire est entrées moins sorties.', 1),
    ('cabefad3-8688-53cc-9cc2-8666c7991e09'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Qu’est-ce qui explique surtout l’explosion démographique depuis 1800 ?', 'mcq', '["L’effondrement de la mortalité","Une hausse brutale de la natalité","Les migrations","L’allongement de la scolarité"]'::jsonb, 0, 'Médecine, vaccins, eau potable, alimentation.', 2),
    ('ffaad076-187c-5554-b3d9-64e3e5e13445'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Qu’est-ce que la transition démographique ?', 'mcq', '["Le passage d’un régime à forte natalité et mortalité à un régime à faible natalité et mortalité","Une migration massive","Le vieillissement d’une population","L’urbanisation"]'::jsonb, 0, 'Entre les deux, la population explose.', 3),
    ('199f0559-38b5-5f49-a895-91419b0482cc'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Quelle région connaît aujourd’hui la plus forte croissance démographique ?', 'mcq', '["L’Afrique subsaharienne","L’Europe","Le Japon","La Chine"]'::jsonb, 0, 'Sa population pourrait doubler d’ici 2050.', 4),
    ('090a13ef-dca2-5951-b0e3-8e8d01e5b2b4'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Quel est le seuil de renouvellement des générations ?', 'mcq', '["2,1 enfants par femme","1 enfant par femme","3 enfants par femme","2,5 enfants par femme"]'::jsonb, 0, 'C’est l’indice de fécondité.', 5),
    ('72040f8a-64fc-5d10-8a20-0041497a99cd'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Combien de personnes vivent hors de leur pays de naissance ?', 'mcq', '["Environ 280 millions, soit 3,5 % de l’humanité","Environ 1 milliard","Environ 50 millions","Environ 20 % de l’humanité"]'::jsonb, 0, 'C’est une part relativement faible.', 6),
    ('5bdad0d1-5056-55f7-9125-5c994942b6ee'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Où se font la majorité des migrations internationales ?', 'mcq', '["Entre pays voisins","Des pays pauvres vers les pays riches uniquement","Vers l’Europe uniquement","Vers l’Amérique du Nord uniquement"]'::jsonb, 0, 'C’est l’idée reçue la plus répandue sur le sujet.', 7),
    ('b977d568-37eb-575d-a50a-7de5969d6b1d'::uuid, '6019c31c-9ec3-5fe8-81b1-9f173c20ebdc'::uuid, 'Tous les pays du monde sont au même stade de la transition démographique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce décalage explique l’essentiel des différences actuelles.', 8),
    ('c2f64154-afdf-59bf-8f7c-f3bdd6686af9'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Que signifie « habiter » en géographie ?', 'mcq', '["Occuper, pratiquer, aménager et se représenter un espace","Uniquement y avoir son logement","Y être né","Y travailler seulement"]'::jsonb, 0, 'Le verbe est bien plus large que « loger ».', 1),
    ('fe46cb12-f59c-52d5-990a-30e7af9d76bf'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Qu’est-ce que l’espace périurbain ?', 'mcq', '["Un espace entre ville et campagne, dépendant de la ville pour l’emploi","Le centre-ville","Une zone industrielle","Un espace de très faible densité"]'::jsonb, 0, 'Il est marqué par les maisons individuelles.', 2),
    ('fad3b1c7-45aa-51b8-9d47-d50f125603cf'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Qu’est-ce qu’un habitat dispersé ?', 'mcq', '["Des fermes isolées les unes des autres","Un village dense autour d’une place","Des maisons le long d’une route","Un quartier de tours"]'::jsonb, 0, 'Le bocage de l’Ouest français en est un exemple.', 3),
    ('89f8bee0-1571-546a-9d2e-4e8a9869877d'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Qu’est-ce qu’un habitat linéaire ?', 'mcq', '["Un habitat installé le long d’une route, d’un fleuve ou d’une côte","Un habitat groupé autour d’une église","Des fermes isolées","Un habitat en hauteur"]'::jsonb, 0, 'La forme suit un axe.', 4),
    ('742bb32f-2871-58e0-ba99-efafe388474e'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Qu’est-ce que la métropolisation ?', 'mcq', '["La concentration des fonctions rares dans quelques très grandes villes","L’étalement de la ville sur les campagnes","Le vidage des campagnes","La construction de métros"]'::jsonb, 0, 'Elle renforce le poids des métropoles.', 5),
    ('da8b9243-9f7b-5d46-9589-1a676cf7bf1c'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Qu’est-ce que la périurbanisation ?', 'mcq', '["L’étalement de la ville sur les campagnes proches","La densification du centre-ville","L’abandon des campagnes","La création de parcs urbains"]'::jsonb, 0, 'Elle consomme des terres agricoles.', 6),
    ('ce80b279-4e9e-562d-a18d-109b73a3c042'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Qu’est-ce qui relie les différents types d’espaces ?', 'mcq', '["Des réseaux : routes, voies ferrées, câbles, électricité","Rien, ils sont indépendants","Uniquement les frontières","Seulement les fleuves"]'::jsonb, 0, 'Aucun espace n’est autosuffisant.', 7),
    ('5e0709b9-0b69-5bf6-9548-49c4bdab79e9'::uuid, '0c8276c2-eda5-5fcf-bdbf-b36d3b01b1ae'::uuid, 'Un espace rural peut vivre en autosuffisance totale, sans lien avec la ville.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en dépend pour les services, comme la ville dépend de lui pour l’alimentation.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 330 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 330 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
